parts.text:
[
  {
    "statement": "Based on evidence from fishery closure studies, long-term and temporary fishery closures show markedly different effects on marine fish abundance.",
    "citations": []
  },
  {
    "statement": "Long-term fishery closures demonstrated more positive outcomes for marine fish abundance.",
    "citations": []
  },
  {
    "statement": "Two site comparison studies found a higher abundance of fish species in areas closed to groundfish fisheries for six to eight years compared to open areas.",
    "citations": [
      "2655"
    ]
  },
  {
    "statement": "One study found more young salmon returning to rivers in the five years after the long-term closure of a commercial coastal fishery.",
    "citations": [
      "2655"
    ]
  },
  {
    "statement": "Temporary fishery closures showed limited or no positive effects on fish abundance.",
    "citations": []
  },
  {
    "statement": "One study in the Atlantic Ocean found no increase in the biomass of the spawning stock of cod following a temporary fishery closure compared to fished areas over nine years.",
    "citations": [
      "2664"
    ]
  },
  {
    "statement": "A study in the Atlantic Ocean found no change in cod catches following a temporary fishery closure when compared to fished areas.",
    "citations": [
      "2664"
    ]
  },
  {
    "statement": "The evidence suggests that long-term closures can lead to increased fish abundance and biomass in protected areas.",
    "citations": []
  },
  {
    "statement": "The evidence suggests that temporary closures may not provide sufficient time for fish populations to recover and show measurable increases in abundance.",
    "citations": []
  }
]

[
  {
    "statement": "Marine Protected Areas that prohibit most or all fishing show significant positive effects on fish abundance and diversity based on extensive research evidence.",
    "citations": []
  },
  {
    "statement": "Thirty of 54 site comparison studies found that marine protected areas prohibiting all fishing for up to 25 years or more had higher abundances of all fish, fishery targeted fish species, and non-fishery targeted fish species compared to unprotected fished areas.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "Five of six reviews across the world found that non-fished marine reserves with one to 27 years of protection had higher abundances of all fish compared to fished areas.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "Five of six reviews across the world found that non-fished marine reserves with one to 27 years of protection had higher abundances of all fish and invertebrates combined compared to fished areas.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "Two systematic reviews found that marine protected areas prohibiting all fishing had greater overall invertebrate abundance and biomass compared to fished areas.",
    "citations": [
      "2224"
    ]
  },
  {
    "statement": "Fourteen of 20 site comparison studies found that marine protected areas that had prohibited all fishing for between one to more than 25 years had higher fish species richness compared to fished areas.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "Six studies found similar fish species richness between one and 20 years after all fishing was banned in protected areas compared to fished areas.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "One systematic review found no difference in species richness between unfished protected areas and fished areas.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "One study found a higher number of fish species in the no-fishing/no access zone of a multi-zoned marine protected area compared to partially fished zones and unprotected fished areas 10 to 15 years after implementation.",
    "citations": [
      "2674"
    ]
  },
  {
    "statement": "Research shows that fish in protected areas are larger than fish in fished areas.",
    "citations": []
  },
  {
    "statement": "Two global review studies and two systematic reviews found that prohibiting all fishing in marine protected areas for one to 27 years resulted in larger fish overall compared to fished areas.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "Eight of 11 site comparison studies found that non-fished protected areas had larger fish overall compared to fished areas, after one to 22 years.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "Eight of 11 site comparison studies found that non-fished protected areas had larger individuals of all or most fish species/groups monitored compared to fished areas, after one to 22 years.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "Changes in fish community composition were observed in protected areas.",
    "citations": []
  },
  {
    "statement": "Seven site comparison studies found that protected areas where all fishing had been prohibited for between three and 16 years had different fish community composition compared to fished areas.",
    "citations": [
      "2682"
    ]
  }
]

[
  {
    "statement": "Several gear modifications beyond hook type changes can reduce unwanted catches of sharks and rays.",
    "citations": []
  },
  {
    "statement": "Increasing the lead weight on mid-water longlines to increase the sinking rate can reduce catches of unwanted sharks and rays compared to standard longlines.",
    "citations": [
      "2699"
    ]
  },
  {
    "statement": "Using nylon instead of wire hook attachments can reduce catches of unwanted sharks and rays compared to standard longlines.",
    "citations": [
      "2699"
    ]
  },
  {
    "statement": "Fishing gear fitted with electropositive deterrent materials can catch fewer unwanted sharks and rays, and fewer undersized halibut, compared to standard fishing gear or gears with non-deterrent materials.",
    "citations": [
      "2696"
    ]
  },
  {
    "statement": "Size-sorting escape grids fitted to prawn or shrimp trawl nets reduce unwanted fish catches by allowing the escape of unwanted sharks and other fish species.",
    "citations": [
      "2721"
    ]
  },
  {
    "statement": "Trawl nets fitted with both a size-sorting escape grid and a large supported escape opening reduce catches of unwanted sharks and rays compared to standard trawl nets.",
    "citations": [
      "2726"
    ]
  },
  {
    "statement": "Bottom trawl nets fitted with square mesh escape panels and size-sorting grids reduce the unwanted catch of sharks and stingrays compared to standard unmodified trawl nets.",
    "citations": [
      "2727"
    ]
  },
  {
    "statement": "Diamond mesh trawl nets with either a top square mesh escape panel or a large supported opening reduce unwanted shark catches compared to standard trawl nets.",
    "citations": [
      "2716"
    ]
  },
  {
    "statement": "The use of a top square mesh escape panel or a large supported opening in diamond mesh trawl nets was not effective for reducing catches of rays and sawfish.",
    "citations": [
      "2716"
    ]
  },
  {
    "statement": "Rigid escape windows fitted to trawl nets can reduce unwanted flatfish catches.",
    "citations": [
      "2719"
    ]
  },
  {
    "statement": "LED lights fitted to fishing lines on shrimp trawl nets reduce catches of unwanted fish compared to conventional trawls.",
    "citations": [
      "2695"
    ]
  }
]

[
  {
    "statement": "Several gear modifications are available to reduce unwanted catch of cod and haddock in the North Sea.",
    "citations": []
  },
  {
    "statement": "Separator trawls have been found to be effective at reducing unwanted catch.",
    "citations": [
      "2711"
    ]
  },
  {
    "statement": "One study in the North Sea showed that a separator trawl separated unwanted cod from target fish species into the lower codend.",
    "citations": [
      "2711"
    ]
  },
  {
    "statement": "A larger mesh size in the lower codend of a separator trawl allowed more unwanted smaller cod to escape capture.",
    "citations": [
      "2711"
    ]
  },
  {
    "statement": "Topless or coverless trawls showed mixed results in North Sea studies for reducing unwanted catch.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "One study found that topless trawls reduced unwanted catches of larger haddock but not smaller haddock.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "The same study found that topless trawls reduced unwanted catches of larger Atlantic cod in only one of two cases compared to standard trawl types.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "Size-sorting escape grids, which can be rigid or flexible, have proven effective at reducing unwanted catch.",
    "citations": [
      "2720"
    ]
  },
  {
    "statement": "Eleven of fourteen replicated studies found that fitting size-sorting escape grids to fish trawl nets reduced catches of unwanted sizes of cod and other non-target fish.",
    "citations": [
      "2720"
    ]
  },
  {
    "statement": "Two of three replicated studies in the North Sea and Norwegian Sea found that size-sorting escape grids fitted to trawl nets improved the size-selection of haddock.",
    "citations": [
      "2720"
    ]
  },
  {
    "statement": "These studies found that size-sorting escape grids did not improve the size-selection of cod, compared to standard nets without grids.",
    "citations": [
      "2720"
    ]
  },
  {
    "statement": "Mesh escape panels or windows fitted to trawl nets showed effectiveness in North Sea studies.",
    "citations": [
      "2716"
    ]
  },
  {
    "statement": "Fourteen of nineteen replicated studies found that square mesh escape panels or windows fitted to diamond mesh trawl nets reduced unwanted catches of all fish species monitored.",
    "citations": [
      "2716"
    ]
  },
  {
    "statement": "Using square mesh codends instead of diamond mesh codends has also proved beneficial.",
    "citations": [
      "2725"
    ]
  },
  {
    "statement": "Three replicated studies found that trawl nets with an escape grid and a square mesh codend caught fewer unwanted cod and haddock compared to a diamond mesh codend with no grid.",
    "citations": [
      "2725"
    ]
  }
]

[
  {
    "statement": "Mesh escape panels, size-sorting grids, and large supported openings show different levels of effectiveness for improving size-selectivity in trawl nets.",
    "citations": []
  },
  {
    "statement": "Studies on mesh escape panels show mixed results for size-selectivity improvement.",
    "citations": [
      "2717"
    ]
  },
  {
    "statement": "Some studies found that modifying the position and/or size of mesh escape panels improved the size-selectivity of haddock and whiting.",
    "citations": [
      "2717"
    ]
  },
  {
    "statement": "Other studies found that size-selectivity for cod was similar when using mesh escape panels compared to standard trawls.",
    "citations": [
      "2717"
    ]
  },
  {
    "statement": "One study found that when mesh escape panels were combined with size-sorting grids, the size-selectivity of whiting was increased compared to standard nets.",
    "citations": [
      "2727"
    ]
  },
  {
    "statement": "Size-sorting grids demonstrate more consistent effectiveness for improving size-selectivity.",
    "citations": []
  },
  {
    "statement": "Some studies found that size-sorting escape grids improved size-selection of haddock, but not of saithe or cod, compared to standard nets without grids.",
    "citations": [
      "2720"
    ]
  },
  {
    "statement": "Different designs and configurations of size-sorting grids show variable results.",
    "citations": [
      "2728"
    ]
  },
  {
    "statement": "Some studies found certain designs of size-sorting grids provided better size-selectivity for unwanted redfish, Greenland halibut, and commercial target hake compared to other designs.",
    "citations": [
      "2728"
    ]
  },
  {
    "statement": "Several studies found that the effects of size-sorting grids on size-selectivity varied between different fish species.",
    "citations": [
      "2728"
    ]
  },
  {
    "statement": "At least one study found that size-sorting grids resulted in no improvement in size-selectivity.",
    "citations": [
      "2728"
    ]
  },
  {
    "statement": "When combined with square mesh codends, size-sorting grids effectively reduced unwanted catches of whiting, plaice, cod, and haddock.",
    "citations": [
      "2725"
    ]
  },
  {
    "statement": "The combination of size-sorting grids and square mesh codends did not effectively reduce unwanted catches of hake.",
    "citations": [
      "2725"
    ]
  },
  {
    "statement": "Evidence shows large supported openings are primarily effective for reducing unwanted catch rather than improving size-selectivity.",
    "citations": []
  },
  {
    "statement": "Studies found that large supported escape openings, including Fisheyes, Bigeyes and radial escape sections, reduced overall catches of unwanted fish and immature red snapper compared to standard nets.",
    "citations": [
      "2723"
    ]
  },
  {
    "statement": "No specific size-selectivity improvements were reported in studies of large supported escape openings.",
    "citations": [
      "2723"
    ]
  },
  {
    "statement": "When large supported openings were combined with grids, studies found reduced catches of unwanted fish, sharks, and rays.",
    "citations": [
      "2726"
    ]
  },
  {
    "statement": "The combination of mesh escape panels with size-sorting grids appears more effective than using the individual devices alone.",
    "citations": [
      "2727"
    ]
  },
  {
    "statement": "Studies have shown that using both mesh escape panels and size-sorting grids together can reduce unwanted catch and improve size-selectivity.",
    "citations": [
      "2727"
    ]
  }
]

[
  {
    "statement": "Based on the available evidence, there are limited direct comparative studies between prohibiting all static fishing gear versus prohibiting only line fishing.",
    "citations": []
  },
  {
    "statement": "One study in the Coral Sea, Australia, found that areas closed to non-towed fishing gears had higher overall shark abundance when sampled with longlines but not gillnets compared to areas where commercial gillnets were permitted.",
    "citations": [
      "2670"
    ]
  },
  {
    "statement": "The same study in the Coral Sea found that shark length was greater for two of five species or groups, similar for two, and dependent on sampling gear for one species in closed areas compared to areas where commercial gillnets were permitted.",
    "citations": [
      "2670"
    ]
  },
  {
    "statement": "A study in the Indian Ocean, South Africa, found that prohibiting offshore line fishing and all other boat-based fishing in a marine protected area zone resulted in higher abundances of four of four fish species over-exploited by line fishing.",
    "citations": [
      "2671"
    ]
  },
  {
    "statement": "These higher abundances were found when compared to two zones where boat-based line and spear fishing was permitted.",
    "citations": [
      "2671"
    ]
  },
  {
    "statement": "The same study in the Indian Ocean found that four of four fish species over-exploited by line fishing were larger in the protected zone which had been closed for two to seven years.",
    "citations": [
      "2671"
    ]
  },
  {
    "statement": "The evidence suggests that both prohibiting all static fishing gear and prohibiting only line fishing can increase fish abundance.",
    "citations": []
  },
  {
    "statement": "The studies on these different prohibition approaches examined different fish groups, such as sharks for static gear prohibition and line-targeted species for line fishing prohibition.",
    "citations": []
  },
  {
    "statement": "The studies also examined different geographic regions, making direct comparison difficult based on available data.",
    "citations": []
  }
]

[
  {
    "statement": "Marine protected areas with zonation systems that permit some fishing show variable outcomes for fish populations depending on the level of restrictions in different zones.",
    "citations": []
  },
  {
    "statement": "In marine protected areas with zonation systems, fish abundance and biomass varied with the level of restriction between zones.",
    "citations": [
      "2674"
    ]
  },
  {
    "statement": "Non-fished zones (no-entry and no-take) showed higher density, biomass, and abundance of fish compared to fished zones inside areas protected for 10 to 27 years.",
    "citations": [
      "2674"
    ]
  },
  {
    "statement": "The effects of zonation systems on fish populations varied between fish feeding groups, zone protection level, and reef region.",
    "citations": [
      "2674"
    ]
  },
  {
    "statement": "Fish abundance and size were generally largest within no-take zones compared to partially fished zones within the same marine protected area system.",
    "citations": [
      "2674"
    ]
  },
  {
    "statement": "One study found a higher number of fish species in the no-fishing/no access zone of a multi-zoned marine protected area compared to two partially fished zones and unprotected fished areas 10 to 15 years after implementation.",
    "citations": [
      "2674"
    ]
  },
  {
    "statement": "Controlling human activity in marine protected areas with zonation systems resulted in larger average lengths of steentjies and three seabream species compared to unprotected fished areas.",
    "citations": [
      "2674"
    ]
  },
  {
    "statement": "The average lengths of steentjies and three seabream species were largest within a no-take zone compared to a partially fished zone.",
    "citations": [
      "2674"
    ]
  },
  {
    "statement": "Larger sizes were found for four of four studied coral reef fish species in zones where nearly all fishing is prohibited compared to adjacent zones with fewer fishing restrictions two to seven years after protection.",
    "citations": [
      "2674"
    ]
  },
  {
    "statement": "Most individuals of reef fish species tagged and released inside protected areas were recaptured again at almost the same locations over four to nine years.",
    "citations": [
      "2674"
    ]
  },
  {
    "statement": "The recaptured reef fish were mainly found in zones where all or nearly all fishing was prohibited, indicating increased protection from fishing.",
    "citations": [
      "2674"
    ]
  },
  {
    "statement": "One study found that restricting all fishing activity except for bait fishing in marine protected areas for seven years resulted in similar total fish biomass and lower total fish density compared to unprotected areas.",
    "citations": [
      "2681"
    ]
  }
]

[
  {
    "statement": "The effectiveness of prohibiting mobile bottom fishing gear varies between regions, with studies from the North Atlantic, Mediterranean, and Indian Ocean showing different outcomes.",
    "citations": []
  },
  {
    "statement": "In the North Atlantic Ocean, studies on the prohibition of bottom trawling found mixed results.",
    "citations": [
      "2673"
    ]
  },
  {
    "statement": "One study in the North Atlantic Ocean showed increased total fish biomass after 15 years in areas closed to bottom trawling.",
    "citations": [
      "2673"
    ]
  },
  {
    "statement": "Another North Atlantic study found no effect on the abundance of bottom-dwelling fish species after 10 years of a bottom trawling closure.",
    "citations": [
      "2673"
    ]
  },
  {
    "statement": "North Atlantic studies showed no increases in haddock recruitment or survival seven years after a bottom trawling closure.",
    "citations": [
      "2673"
    ]
  },
  {
    "statement": "In the Mediterranean Sea, the effectiveness of closing areas to bottom-towed fishing gears appeared more positive.",
    "citations": [
      "2673",
      "2099"
    ]
  },
  {
    "statement": "Studies in the Mediterranean Sea showed higher biomass of adult red mullet after 14 years in areas closed to bottom-towed fishing gears.",
    "citations": [
      "2673"
    ]
  },
  {
    "statement": "Mediterranean studies also showed increased recruitment of young red mullet after 14 years when areas were closed to bottom-towed fishing gears.",
    "citations": [
      "2673"
    ]
  },
  {
    "statement": "The closure of fishing areas in the Mediterranean also led to increased adult red mullet sizes.",
    "citations": [
      "2673"
    ]
  },
  {
    "statement": "Mediterranean studies of bottom trawling prohibitions showed a different invertebrate community composition compared to trawled areas after 15-20 years.",
    "citations": [
      "2099"
    ]
  },
  {
    "statement": "The effect of bottom trawling prohibitions on invertebrate diversity in the Mediterranean had mixed results depending on the study duration.",
    "citations": [
      "2099"
    ]
  },
  {
    "statement": "In the Indian Ocean, results from prohibiting mobile bottom fishing gears varied significantly between studies and species.",
    "citations": [
      "2673",
      "2667"
    ]
  },
  {
    "statement": "One Indian Ocean study found an increased abundance of long-snouted seahorses, but not short-snouted seahorses, after one year of prohibiting mobile bottom fishing gears.",
    "citations": [
      "2673"
    ]
  },
  {
    "statement": "Another study in the Indian Ocean found that fish catch rates were higher in areas that had prohibited seine nets for 3-6 years.",
    "citations": [
      "2673"
    ]
  },
  {
    "statement": "Indian Ocean studies of complete commercial fishing bans showed larger overall fish sizes in marine reserves after five years compared to fished areas.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "Evidence suggests that the effectiveness of mobile bottom fishing gear prohibitions may depend on regional factors, species studied, enforcement duration, and specific gear types prohibited.",
    "citations": []
  },
  {
    "statement": "Studies in the Mediterranean generally show more consistent positive outcomes from prohibiting mobile bottom fishing gear than studies in the North Atlantic or Indian Ocean.",
    "citations": []
  }
]

[
  {
    "statement": "Separator trawls have been examined in two studies and show specific effectiveness in reducing unwanted catch.",
    "citations": []
  },
  {
    "statement": "One replicated, randomized study in the North Sea found that a separator trawl separated unwanted cod from target fish species into the lower codend.",
    "citations": [
      "2711"
    ]
  },
  {
    "statement": "The lower codend of the separator trawl had a larger mesh size which allowed more unwanted smaller cod to escape capture.",
    "citations": [
      "2711"
    ]
  },
  {
    "statement": "One replicated study in the Atlantic Ocean found that a separator trawl fitted with a square-mesh escape panel caught less of one of two unwanted fish species in a crustacean fishery.",
    "citations": [
      "2711"
    ]
  },
  {
    "statement": "Topless (coverless) trawls have been examined in four studies with variable results.",
    "citations": []
  },
  {
    "statement": "Two of four replicated, controlled studies found that using a topless trawl reduced the catch of unwanted Atlantic cod compared to conventional trawl types.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "Two of four replicated, controlled studies found that using a topless trawl reduced discards of commercial fish species compared to conventional trawl types.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "In one case, a topless trawl was used in combination with another non-conventional trawl type.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "The four replicated, controlled studies on topless trawls took place in the North Sea, Gulf of Maine, and North Sea, Skagerrak and Baltic Sea.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "One study found that topless trawls reduced unwanted catches of larger haddock but not smaller haddock compared to standard trawl types.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "One study found that topless trawls reduced unwanted catches of larger Atlantic cod in only one of two cases, compared to standard trawl types.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "Another study found that discarded catches of one of four commercial fish species were reduced in topless trawls.",
    "citations": [
      "2712"
    ]
  }
]

[
  {
    "statement": "Twenty-three studies examined the effects of modifying fishing trap or pot configuration on marine fish populations across various global locations.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "The studies on fishing trap modifications were conducted in locations including the Atlantic Ocean, Baltic Sea, Mediterranean Sea, Southern Ocean, Tasman Sea, Adriatic Sea, Bothnian Sea, Indian Ocean, Pacific Ocean, the Kattegat and the Barents Sea.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "One study found that the survival of small herring that escaped from a pontoon fish trap through a size-sorting grid was similar to trap-caught herring that did not pass through a grid.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "Sixteen of twenty studies found that modifications to trap configuration reduced unwanted catches of various fish species compared to unmodified conventional traps.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "Modifications to trap configuration that reduced unwanted catches included using different trap types, increased mesh size, and fitting escape devices.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "The fish species with reduced unwanted catches due to trap modifications include brown trout, black sea bass, herring, bluethroat wrasse and leatherjacket, cod, protected rockfishes, whitefish, American eel and winter flounder, and sharks/rays.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "Three studies found that trap modification had no effect on unwanted catches of white croaker, non-commercial fish, or undersized Atlantic cod.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "One study found that trap modifications increased non-target haddock catches.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "Three of four studies found that traps or pots modified with square mesh escape windows or larger mesh sizes improved size-selectivity of Atlantic cod, black sea bass, and most fish species compared to smaller mesh and standard gear.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "One study found that increasing the mesh size of trap escape panels had no effect on the size-selectivity of panga.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "Trap modifications showed effects on marine mammals.",
    "citations": [
      "2822"
    ]
  },
  {
    "statement": "Using steel rods on lobster pots and metal frames on fishing pots reduced sea lion pup and seal entrapments.",
    "citations": [
      "2822"
    ]
  }
]

[
  {
    "statement": "Nine studies examined the effect of attaching electropositive deterrents to fishing gear on marine fish populations.",
    "citations": []
  },
  {
    "statement": "The studies were conducted across the Atlantic Ocean, the Gulf of Alaska, the South Pacific Ocean, the Tasman Sea, and in laboratory facilities.",
    "citations": []
  },
  {
    "statement": "A global systematic review also examined the effect of electropositive deterrents on fishing gear.",
    "citations": [
      "2696"
    ]
  },
  {
    "statement": "Three of four replicated studies found that electropositive deterrent materials attached near bait reduced feeding attempts by spiny dogfish, great hammerhead, and draughtboard sharks compared to gear without deterrents.",
    "citations": []
  },
  {
    "statement": "Three of four replicated studies found that electropositive deterrent materials attached near bait reduced bait consumption by spiny dogfish, great hammerhead, and draughtboard sharks compared to gear without deterrents.",
    "citations": []
  },
  {
    "statement": "One study found no reduction in bait consumption by bonnethead and young lemon sharks when using electropositive deterrents.",
    "citations": []
  },
  {
    "statement": "One study found that the behavior of commercially valuable Pacific halibut was unaffected by deterrent materials.",
    "citations": [
      "2696"
    ]
  },
  {
